import express from "express";
import path from "path";
import cors from "cors";
import { createServer as createViteServer } from "vite";
import Database from "better-sqlite3";
import swaggerJsdoc from "swagger-jsdoc";
import swaggerUi from "swagger-ui-express";

const db = new Database("investpro.db");

// Initialize Database
db.exec(`
  CREATE TABLE IF NOT EXISTS users (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    email TEXT UNIQUE NOT NULL,
    password TEXT NOT NULL,
    name TEXT NOT NULL,
    role TEXT NOT NULL CHECK (role IN ('admin', 'user', 'guest'))
  );

  CREATE TABLE IF NOT EXISTS investors (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    name TEXT NOT NULL,
    organization TEXT NOT NULL,
    amount REAL NOT NULL,
    status TEXT NOT NULL DEFAULT 'active',
    last_investment_date TEXT DEFAULT CURRENT_TIMESTAMP
  );

  CREATE TABLE IF NOT EXISTS documents (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    title TEXT NOT NULL,
    type TEXT NOT NULL,
    size TEXT NOT NULL,
    url TEXT NOT NULL,
    uploaded_by TEXT NOT NULL,
    created_at TEXT DEFAULT CURRENT_TIMESTAMP
  );
`);

// Seed Initial Data if empty
const rowCount = db.prepare("SELECT count(*) as count FROM users").get() as { count: number };
if (rowCount.count === 0) {
  const insert = db.prepare("INSERT INTO users (email, password, name, role) VALUES (?, ?, ?, ?)");
  insert.run("admin@investpro.com", "password", "System Admin", "admin");
  insert.run("user@investpro.com", "password", "Standard User", "user");
  insert.run("guest@investpro.com", "password", "Guest User", "guest");

  const insertInv = db.prepare("INSERT INTO investors (name, organization, amount, status) VALUES (?, ?, ?, ?)");
  insertInv.run("John Doe", "Global Ventures", 500000, "active");
  insertInv.run("Sarah Smith", "Innovation Capital", 250000, "active");

  const insertDoc = db.prepare("INSERT INTO documents (title, type, size, url, uploaded_by) VALUES (?, ?, ?, ?, ?)");
  insertDoc.run("Q4 Financial Report", "PDF", "2.4 MB", "#", "System Admin");
  insertDoc.run("Investor Agreement", "DOCX", "1.1 MB", "#", "System Admin");
}

async function startServer() {
  const app = express();
  const PORT = 3000;
  app.use(express.json());
  app.use(cors());

  // Swagger Documentation
  const swaggerOptions = {
    definition: {
      openapi: "3.0.0",
      info: {
        title: "InvestPro API",
        version: "1.0.0",
        description: "API documentation for the InvestPro investment platform",
      },
      servers: [
        {
          url: "http://localhost:3000",
          description: "Development server",
        },
      ],
    },
    apis: ["./server.ts"],
  };

  const swaggerSpec = swaggerJsdoc(swaggerOptions);
  app.use("/api-docs", swaggerUi.serve, swaggerUi.setup(swaggerSpec));

  /**
   * @openapi
   * /api/login:
   *   post:
   *     summary: User login
   *     tags: [Auth]
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             properties:
   *               email:
   *                 type: string
   *               password:
   *                 type: string
   *     responses:
   *       200:
   *         description: Login successful
   *       401:
   *         description: Invalid credentials
   */
  app.post("/api/login", (req, res) => {
    const { email, password } = req.body;
    try {
      const user = db.prepare("SELECT * FROM users WHERE email = ? AND password = ?").get(email, password) as any;

      if (user) {
        const { password: _, ...userWithoutPassword } = user;
        userWithoutPassword.id = String(userWithoutPassword.id);
        res.json({ token: "mock-jwt-token", user: userWithoutPassword });
      } else {
        res.status(401).json({ message: "Invalid credentials" });
      }
    } catch (err) {
      res.status(500).json({ message: "Database error" });
    }
  });

  /**
   * @openapi
   * /api/register:
   *   post:
   *     summary: Register a new user
   *     tags: [Auth]
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             properties:
   *               email:
   *                 type: string
   *               name:
   *                 type: string
   *               password:
   *                 type: string
   *     responses:
   *       200:
   *         description: Registration successful
   *       400:
   *         description: User already exists
   */
  app.post("/api/register", (req, res) => {
    const { email, name, password } = req.body;
    try {
      const existing = db.prepare("SELECT id FROM users WHERE email = ?").get(email);
      if (existing) {
        return res.status(400).json({ message: "User already exists" });
      }

      const info = db.prepare("INSERT INTO users (email, name, password, role) VALUES (?, ?, ?, ?)").run(email, name, password, "user");
      const newUser = { id: String(info.lastInsertRowid), email, name, role: "user" };
      
      res.json({ token: "mock-jwt-token", user: newUser });
    } catch (err) {
      res.status(500).json({ message: "Registration failed" });
    }
  });

  /**
   * @openapi
   * /api/forgot-password:
   *   post:
   *     summary: Request password reset
   *     tags: [Auth]
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             properties:
   *               email:
   *                 type: string
   *     responses:
   *       200:
   *         description: Reset link sent
   *       404:
   *         description: User not found
   */
  app.post("/api/forgot-password", (req, res) => {
    const { email } = req.body;
    try {
      const user = db.prepare("SELECT id FROM users WHERE email = ?").get(email);
      if (!user) {
        return res.status(404).json({ message: "No account found with this email" });
      }
      // In a real app, send an email with a reset token
      res.json({ message: "Password reset link sent to your email" });
    } catch (err) {
      res.status(500).json({ message: "Failed to process request" });
    }
  });

  /**
   * @openapi
   * /api/reset-password:
   *   post:
   *     summary: Reset password
   *     tags: [Auth]
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             properties:
   *               email:
   *                 type: string
   *               newPassword:
   *                 type: string
   *     responses:
   *       200:
   *         description: Password reset successful
   */
  app.post("/api/reset-password", (req, res) => {
    const { email, newPassword } = req.body;
    try {
      const result = db.prepare("UPDATE users SET password = ? WHERE email = ?").run(newPassword, email);
      if (result.changes === 0) {
        return res.status(404).json({ message: "User not found" });
      }
      res.json({ message: "Password successfully updated" });
    } catch (err) {
      res.status(500).json({ message: "Failed to reset password" });
    }
  });

  /**
   * @openapi
   * /api/users:
   *   get:
   *     summary: Get all users
   *     tags: [Admin]
   *     responses:
   *       200:
   *         description: List of users
   */
  app.get("/api/users", (req, res) => {
    try {
      const users = db.prepare("SELECT id, email, name, role FROM users").all() as any[];
      res.json(users.map(u => ({ ...u, id: String(u.id) })));
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch users" });
    }
  });

  /**
   * @openapi
   * /api/users/{id}/role:
   *   patch:
   *     summary: Update user role
   *     tags: [Admin]
   *     parameters:
   *       - in: path
   *         name: id
   *         required: true
   *         schema:
   *           type: string
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             properties:
   *               role:
   *                 type: string
   *                 enum: [admin, user, guest]
   *     responses:
   *       200:
   *         description: Role updated
   */
  app.patch("/api/users/:id/role", (req, res) => {
    const { id } = req.params;
    const { role } = req.body;
    try {
      db.prepare("UPDATE users SET role = ? WHERE id = ?").run(role, id);
      res.json({ success: true });
    } catch (err) {
      res.status(500).json({ message: "Failed to update role" });
    }
  });

  // Investors API
  /**
   * @openapi
   * /api/investors:
   *   get:
   *     summary: Get all investors
   *     tags: [Investors]
   *     responses:
   *       200:
   *         description: List of investors
   */
  app.get("/api/investors", (req, res) => {
    try {
      const investors = db.prepare("SELECT * FROM investors").all() as any[];
      res.json(investors.map(i => ({ ...i, id: String(i.id) })));
    } catch (err) {
       res.status(500).json({ message: "Failed to fetch investors" });
    }
  });

  /**
   * @openapi
   * /api/investors:
   *   post:
   *     summary: Add new investor
   *     tags: [Investors]
   *     requestBody:
   *       required: true
   *       content:
   *         application/json:
   *           schema:
   *             type: object
   *             properties:
   *               name:
   *                 type: string
   *               organization:
   *                 type: string
   *               amount:
   *                 type: number
   *               status:
   *                 type: string
   *     responses:
   *       200:
   *         description: Investor added
   */
  app.post("/api/investors", (req, res) => {
    const { name, organization, amount, status } = req.body;
    try {
      const info = db.prepare("INSERT INTO investors (name, organization, amount, status) VALUES (?, ?, ?, ?)").run(name, organization, amount, status || "active");
      res.json({ id: String(info.lastInsertRowid), name, organization, amount, status: status || "active" });
    } catch (err) {
      res.status(500).json({ message: "Failed to add investor" });
    }
  });

  app.put("/api/investors/:id", (req, res) => {
    const { id } = req.params;
    const { name, organization, amount, status } = req.body;
    try {
      db.prepare("UPDATE investors SET name = ?, organization = ?, amount = ?, status = ? WHERE id = ?").run(name, organization, amount, status, id);
      res.json({ success: true });
    } catch (err) {
      res.status(500).json({ message: "Failed to update investor" });
    }
  });

  app.delete("/api/investors/:id", (req, res) => {
    try {
      db.prepare("DELETE FROM investors WHERE id = ?").run(req.params.id);
      res.json({ success: true });
    } catch (err) {
      res.status(500).json({ message: "Failed to delete investor" });
    }
  });

  // Documents API
  /**
   * @openapi
   * /api/documents:
   *   get:
   *     summary: Get all documents
   *     tags: [Documents]
   *     responses:
   *       200:
   *         description: List of documents
   */
  app.get("/api/documents", (req, res) => {
    try {
      const documents = db.prepare("SELECT * FROM documents").all() as any[];
      res.json(documents.map(d => ({ ...d, id: String(d.id) })));
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch documents" });
    }
  });

  app.post("/api/documents", (req, res) => {
    const { title, type, size, url, uploaded_by } = req.body;
    try {
      const info = db.prepare("INSERT INTO documents (title, type, size, url, uploaded_by) VALUES (?, ?, ?, ?, ?)").run(title, type, size, url || "#", uploaded_by);
      res.json({ id: String(info.lastInsertRowid), title, type, size, url: url || "#", uploaded_by });
    } catch (err) {
      res.status(500).json({ message: "Failed to add document" });
    }
  });

  app.delete("/api/documents/:id", (req, res) => {
    try {
      db.prepare("DELETE FROM documents WHERE id = ?").run(req.params.id);
      res.json({ success: true });
    } catch (err) {
      res.status(500).json({ message: "Failed to delete document" });
    }
  });

  // Stats API
  /**
   * @openapi
   * /api/stats:
   *   get:
   *     summary: Get platform stats
   *     tags: [Stats]
   *     responses:
   *       200:
   *         description: Platform statistics
   */
  app.get("/api/stats", (req, res) => {
    try {
      const userCount = db.prepare("SELECT COUNT(*) as count FROM users").get() as any;
      const investorCount = db.prepare("SELECT COUNT(*) as count FROM investors").get() as any;
      const totalInvestment = db.prepare("SELECT SUM(amount) as total FROM investors").get() as any;
      const documentCount = db.prepare("SELECT COUNT(*) as count FROM documents").get() as any;

      res.json({
        users: userCount.count,
        investors: investorCount.count,
        investment: totalInvestment.total || 0,
        documents: documentCount.count
      });
    } catch (err) {
      res.status(500).json({ message: "Failed to fetch stats" });
    }
  });

  // Vite middleware for development
  if (process.env.NODE_ENV !== "production") {
    const vite = await createViteServer({
      server: { middlewareMode: true },
      appType: "spa",
    });
    app.use(vite.middlewares);
  } else {
    const distPath = path.join(process.cwd(), "dist");
    app.use(express.static(distPath));
    app.get("*", (req, res) => {
      res.sendFile(path.join(distPath, "index.html"));
    });
  }

  app.listen(PORT, "0.0.0.0", () => {
    console.log(`Server running on http://0.0.0.0:${PORT}`);
  });
}

startServer();
